  // Music button clicks are handled by the document-level delegation (runChromeActionFromEvent)
  // which calls handleChromeAction → toggleChromeMusic. No direct handler needed here
  // to avoid double-toggle with the delegation or CollectionPreviewPage's injection.

  function toggleChromeMusic(btn, opts = {}) {
    const forcePlay = !!opts.forcePlay;

    let audio =
      document.getElementById('hiweb-background-music') ||
      document.getElementById('bgMusic') ||
      document.getElementById('background-music');

    const url = (btn && btn.getAttribute && btn.getAttribute('data-music-url')) || (btn && btn.dataset && btn.dataset.musicUrl) || (btn && btn.dataset && btn.dataset.music_url) || '';

    if (!audio && url) {
      audio = document.createElement('audio');
      audio.id = 'hiweb-background-music';
      audio.loop = true;
      audio.muted = false;
      audio.src = url;
      document.body.appendChild(audio);
    }

    if (!audio) return;

    if (forcePlay) {
      if (!audio.paused) return Promise.resolve(true);
      audio.muted = false;
      syncMusicButtonState(true);
      return audio.play().then(() => {
        return true;
      }).catch((err) => {
        syncMusicButtonState(false);
        try { window.__hiwebNeedScrollToPlay = true; } catch (e) {}
        return Promise.reject(err);
      });
    }

    if (audio.paused) {
      audio.muted = false;
      syncMusicButtonState(true);
      return audio.play().then(() => {
        return true;
      }).catch(() => {
        syncMusicButtonState(false);
      });
    } else if (audio.muted) {
      audio.muted = false;
      syncMusicButtonState(true);
      return audio.play().then(() => {
        return true;
      }).catch(() => {
        syncMusicButtonState(false);
      });
    } else {
      audio.pause();
      syncMusicButtonState(false);
      return Promise.resolve(false);
    }
  }

  function syncMusicButtonState(isPlaying) {
    const selectors = [
      '#chrome-music-btn',
      '#musicToggle',
      '.music-btn',
      '.hiweb-music-fab',
      '[data-chrome-action="music"]'
    ];
    const allBtns = new Set();
    selectors.forEach(function(sel) {
      document.querySelectorAll(sel).forEach(function(el) { allBtns.add(el); });
    });
    allBtns.forEach(function(btn) {
      if (!btn) return;
      btn.classList.toggle('playing', !!isPlaying);
      btn.classList.toggle('is-playing', !!isPlaying);
      btn.setAttribute('data-hiweb-music-active', isPlaying ? 'true' : 'false');
      if (btn.style.getPropertyValue('display') !== 'none' && btn.style.display !== 'none') {
        btn.style.display = 'flex';
      }
    });
  }

  // Autoplay logic for published public URL:
  // Flow: user interaction (scroll/click) → play unmuted → icon spins
  (function initChromeMusicAutoplay() {
  try {
    var _audio = null;
    var _started = false;   // muted play đã chạy chưa
    var _unmuted = false;   // đã unmute chưa

    function buildAudio() {
      var btn =
        document.getElementById('chrome-music-btn') ||
        document.getElementById('chrome-music-btn-mobile') ||
        document.querySelector('[data-chrome-action="music"]');
      if (btn && (btn.style.display === 'none' || btn.style.getPropertyValue('display') === 'none')) return null;
      var url = btn && (
        btn.getAttribute('data-music-url') ||
        (btn.dataset && (btn.dataset.musicUrl || btn.dataset.music_url))
      );
      if (!url) return null;

      var a = document.createElement('audio');
      a.id   = 'hiweb-background-music';
      a.loop = true;
      a.volume = 1;
      a.muted = true;
      a.playsInline = true;
      a.setAttribute('playsinline', '');
      a.preload = 'auto';
      var s  = document.createElement('source');
      s.src  = url;
      s.type = 'audio/mpeg';
      a.appendChild(s);
      document.body.appendChild(a);
      return a;
    }

    function getAudio() {
      if (_audio) return _audio;
      _audio =
        document.getElementById('hiweb-background-music') ||
        document.getElementById('bgMusic') ||
        document.getElementById('background-music');
      if (_audio) { _audio.removeAttribute('autoplay'); return _audio; }
      _audio = buildAudio();
      return _audio;
    }

    // Bước 1: muted play — browser luôn cho phép, không cần gesture
    function mutedPlay() {
      if (_started) return;
      var a = getAudio();
      if (!a) return;
      _started = true;
      a.muted = true;
      a.play().catch(function() {
        _started = false; // thử lại nếu fail
      });
    }

    // Bước 2: unmute — KHÔNG cần gesture vì không gọi play() mới
    // Đây là điểm mấu chốt: set muted=false trên audio đang play không bị chặn
    function doUnmute() {
      if (_unmuted) return;
      var a = getAudio();
      if (!a) return;

      // Nếu chưa start được, thử play unmuted luôn (trường hợp có gesture)
      if (!_started || a.paused) {
        _unmuted = true;
        a.muted = false;
        a.play()
          .then(function() { syncMusicButtonState(true); })
          .catch(function() { _unmuted = false; });
        return;
      }

      // Audio đang play muted → chỉ cần unmute, không cần gesture
      _unmuted = true;
      a.muted = false;
      syncMusicButtonState(true);
    }

    function onAnyEvent(e) {
      if (_started && _unmuted) return;
      // Skip clicks on music button – let toggleChromeMusic handle it exclusively
      if (e && e.target && e.target.closest && e.target.closest('#final-mobile-chrome [data-chrome-action="music"]')) return;
      if (!_started) mutedPlay(); // đảm bảo muted play trước
      doUnmute();
    }

    // Gắn lên document với capture:true — bắt mọi event trước khi bị chặn
    // DOMContentLoaded xong mới gắn để đảm bảo document tồn tại
    var EVENTS = ['wheel', 'scroll', 'touchstart', 'touchmove',
                  'pointerdown', 'pointermove', 'click', 'keydown'];

    function attachListeners() {
      EVENTS.forEach(function(evt) {
        document.addEventListener(evt, onAnyEvent, { capture: true, passive: true, once: false });
      });
    }

    // Gắn ngay lập tức (capture phase, passive)
    attachListeners();

    // Muted play ngay khi có thể — không cần đợi gesture
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', mutedPlay);
    } else {
      mutedPlay();
    }
    // Thử lại nhiều lần để đảm bảo audio đã load xong
    setTimeout(mutedPlay, 200);
    setTimeout(mutedPlay, 600);
    setTimeout(mutedPlay, 1500);

    // Cleanup sau khi unmute thành công
    function cleanup() {
      EVENTS.forEach(function(evt) {
        document.removeEventListener(evt, onAnyEvent, true);
      });
    }

    // Theo dõi khi unmute xong thì cleanup
    var _cleanupTimer = setInterval(function() {
      if (_unmuted) {
        clearInterval(_cleanupTimer);
        cleanup();
      }
    }, 500);

  } catch(e) {}
})();

// ── Inject sparkle particles vào wish-scroll-viewport ──
(function injectSparkles() {
  const vp = document.getElementById('wish-scroll-viewport');
  if (!vp) return;

  vp.style.overflow = 'hidden';

  const sparkleCount = 14;
  const sizes = ['size-sm', '', 'size-lg'];
  const colors = [
    'rgba(255,182,193,0.95)',
    'rgba(255,105,150,0.85)',
    'rgba(255,220,230,1)',
    'rgba(255,255,255,0.9)',
    'rgba(255,160,200,0.9)',
  ];

  function starSVG(color) {
    return '<svg viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg"><path d="M10 0 L11.8 8.2 L20 10 L11.8 11.8 L10 20 L8.2 11.8 L0 10 L8.2 8.2 Z" fill="' + color + '"/></svg>';
  }

  for (let i = 0; i < sparkleCount; i++) {
    const el = document.createElement('div');
    el.className = 'wish-sparkle ' + sizes[Math.floor(Math.random() * sizes.length)];

    el.style.left = (Math.random() * 95) + '%';
    el.style.top  = (Math.random() * 90) + '%';

    const delay    = (Math.random() * 3).toFixed(2) + 's';
    const duration = (1.4 + Math.random() * 2).toFixed(2) + 's';
    const driftDur = (2.5 + Math.random() * 2.5).toFixed(2) + 's';

    el.style.animationDelay    = delay;
    el.style.animationDuration = driftDur + ', ' + duration;  // ← dùng + thay vì template literal

    const color = colors[Math.floor(Math.random() * colors.length)];
    el.innerHTML = starSVG(color);

    vp.appendChild(el);
  }
})();

  // RSVP attendance toggle
  root.querySelectorAll('[data-rsvp-att]').forEach((btn) => {
    btn.addEventListener('click', () => {
      root.querySelectorAll('[data-rsvp-att]').forEach((b) => b.classList.remove('selected'));
      btn.classList.add('selected');
      const guestsSection = root.querySelector('#chrome-rsvp-guests-section');
      if (guestsSection) {
        guestsSection.style.display = btn.getAttribute('data-rsvp-att') === 'attending' ? '' : 'none';
      }
    }, { passive: true });
  });

  // RSVP event toggle (multi-select)
  root.querySelectorAll('[data-rsvp-evt]').forEach((btn) => {
    btn.addEventListener('click', () => btn.classList.toggle('selected'), { passive: true });
  });

